def compute(vars):
    x0 = vars["Gross Profit"]
    x1 = vars["Sales"]
    x2 = vars["100"]

    trace = {
        "Gross Profit": x0,
        "Sales": x1,
        "100": x2,
        "input_meta": {
            "Gross Profit": {"currency": "USD", "scale": "million", "unit": None},
            "Sales": {"currency": "USD", "scale": "million", "unit": None},
            "100": {}
        },
        "output_meta": {
            "currency": None,
            "scale": None,
            "unit": "percentage"
        }
    }

    if x1 == 0:
        return {"value": None, "trace": trace}

    gross_margin = (x0 / x1) * x2

    return {
        "value": gross_margin,
        "trace": trace
    }
